/* ===================== BÀI 7 · Xu hướng multicore, SoC, GPU, AI accelerator; giới hạn của Moore ===================== */
/* Bài 7 · Xu hướng multicore, SoC, GPU, AI accelerator; giới hạn của Moore (CM00.07) — sinh bởi tools/author/maytinh/m07.py, không sửa tay.
   Phòng mô phỏng từng bước và bài tập chấm tự động; phần chữ bài học ở lesson.html (nội dung bảo vệ). */
makeMtLab(document.getElementById("lab-l7"),{id:"l7",scenarios:[{"label": "Ví dụ: Nhân đôi mỗi 2 năm từ 2 300 transistor", "note": "Số liệu tính theo mô hình, không phải số transistor của chip thật sau 1971.", "steps": [{"t": "1971: khoảng 2 300 transistor (Intel 4004)", "html": "<p class=\"mt-calc\">Mô hình: N(năm) = 2 300 × 2<sup>(năm − 1971) ÷ 2<\/sup><\/p>", "say": "<p>Đây là phép tính theo đúng nhịp “gấp đôi mỗi 2 năm”, không phải số liệu của một chip cụ thể nào sau 1971.<\/p>"}, {"t": "1981: × 2^5 → khoảng 73 600", "html": "<p class=\"mt-calc\">2 300 × 2<sup>5<\/sup> = <b>73 600<\/b><\/p><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Năm<\/th><th scope=\"col\">Số transistor theo mô hình<\/th><\/tr><\/thead><tbody><tr><td>1971<\/td><td>2 300<\/td><\/tr><tr><td>1981<\/td><td>73 600<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "Sau 10 năm, nhân đôi mỗi 2 năm thì số transistor gấp bao nhiêu lần?", "o": ["10 lần", "20 lần", "32 lần"], "a": 2}}, {"t": "1991: × 2^10 → khoảng 2 355 200", "html": "<p class=\"mt-calc\">2 300 × 2<sup>10<\/sup> = <b>2 355 200<\/b><\/p><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Năm<\/th><th scope=\"col\">Số transistor theo mô hình<\/th><\/tr><\/thead><tbody><tr><td>1971<\/td><td>2 300<\/td><\/tr><tr><td>1981<\/td><td>73 600<\/td><\/tr><tr><td>1991<\/td><td>2 355 200<\/td><\/tr><\/tbody><\/table>"}, {"t": "2001: × 2^15 → khoảng 75 366 400", "html": "<p class=\"mt-calc\">2 300 × 2<sup>15<\/sup> = <b>75 366 400<\/b><\/p><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Năm<\/th><th scope=\"col\">Số transistor theo mô hình<\/th><\/tr><\/thead><tbody><tr><td>1971<\/td><td>2 300<\/td><\/tr><tr><td>1981<\/td><td>73 600<\/td><\/tr><tr><td>1991<\/td><td>2 355 200<\/td><\/tr><tr><td>2001<\/td><td>75 366 400<\/td><\/tr><\/tbody><\/table>"}, {"t": "2011: × 2^20 → khoảng 2 411 724 800", "html": "<p class=\"mt-calc\">2 300 × 2<sup>20<\/sup> = <b>2 411 724 800<\/b><\/p><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Năm<\/th><th scope=\"col\">Số transistor theo mô hình<\/th><\/tr><\/thead><tbody><tr><td>1971<\/td><td>2 300<\/td><\/tr><tr><td>1981<\/td><td>73 600<\/td><\/tr><tr><td>1991<\/td><td>2 355 200<\/td><\/tr><tr><td>2001<\/td><td>75 366 400<\/td><\/tr><tr><td>2011<\/td><td>2 411 724 800<\/td><\/tr><\/tbody><\/table>"}, {"t": "2021: × 2^25 → khoảng 77 tỉ", "html": "<p class=\"mt-calc\">2 300 × 2<sup>25<\/sup> = <b>77 175 193 600<\/b><\/p><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Năm<\/th><th scope=\"col\">Số transistor theo mô hình<\/th><\/tr><\/thead><tbody><tr><td>1971<\/td><td>2 300<\/td><\/tr><tr><td>1981<\/td><td>73 600<\/td><\/tr><tr><td>1991<\/td><td>2 355 200<\/td><\/tr><tr><td>2001<\/td><td>75 366 400<\/td><\/tr><tr><td>2011<\/td><td>2 411 724 800<\/td><\/tr><tr><td>2021<\/td><td>77 175 193 600<\/td><\/tr><\/tbody><\/table>", "say": "<p>Sau 50 năm, mô hình cho khoảng 77 tỉ, cùng cỡ với những chip lớn nhất đầu thập niên 2020 (hàng chục tỉ transistor). Nhịp tăng thực tế có lúc nhanh, lúc chậm và ngày càng tốn kém hơn để giữ.<\/p>"}]}, {"label": "Ví dụ: Tăng xung nhịp và công suất", "note": "P ≈ αCV²f: điện áp nằm trong bình phương. Mức tăng 20% điện áp là giả định.", "steps": [{"t": "Chip gốc: công suất động quy về 1", "html": "<p class=\"mt-calc\">P ≈ α · C · V² · f · đặt P<sub>gốc<\/sub> = 1 (α, C không đổi)<\/p>", "say": "<p>Mô hình gần đúng cho phần công suất do transistor đóng ngắt; chưa tính công suất rò (Chương 2, bài cuối).<\/p>"}, {"t": "Tăng f gấp 2, giữ V: P gấp 2", "html": "<p class=\"mt-calc\">P = 1 × 1² × 2 = <b>2<\/b><\/p><div class=\"mt-bars\"><div><span>Gốc<\/span><span><i class=\"\" style=\"width:33.3%\"><\/i><em>1<\/em><\/span><\/div><div><span>f × 2<\/span><span><i class=\"w\" style=\"width:66.7%\"><\/i><em>2<\/em><\/span><\/div><\/div>", "ask": {"q": "Giữ nguyên V, tăng xung nhịp f gấp đôi. Công suất động gấp mấy lần?", "o": ["2 lần", "4 lần", "Không đổi"], "a": 0}}, {"t": "Muốn f × 2 thường phải tăng V (giả định +20%): P gấp 2,88", "html": "<p class=\"mt-calc\">P = 1,2² × 2 = 1,44 × 2 = <b>2,88<\/b><\/p><div class=\"mt-bars\"><div><span>Gốc<\/span><span><i class=\"\" style=\"width:33.3%\"><\/i><em>1<\/em><\/span><\/div><div><span>f × 2<\/span><span><i class=\"w\" style=\"width:66.7%\"><\/i><em>2<\/em><\/span><\/div><div><span>f × 2, V × 1,2<\/span><span><i class=\"e\" style=\"width:96.0%\"><\/i><em>2,88<\/em><\/span><\/div><\/div>", "say": "<p>Transistor đóng ngắt nhanh hơn thường cần điện áp cao hơn. V nằm trong <b>bình phương<\/b>, nên công suất và nhiệt tăng nhanh hơn xung nhịp. Đó là “bức tường điện năng” từ khoảng giữa thập niên 2000.<\/p>"}]}, {"label": "Ví dụ: Một nhân nhanh hay hai nhân chậm", "note": "Hai nhân ở 0,8f, 0,8V: gần cùng công suất, tối đa 1,6 lần công việc.", "steps": [{"t": "Một nhân: f, V → công suất 1, công việc 1", "html": "<p class=\"mt-calc\">P = 1 · tốc độ xử lý = 1<\/p>", "say": "<p>So sánh với hai nhân giống hệt nhau, mỗi nhân chạy chậm hơn một chút.<\/p>"}, {"t": "Mỗi nhân chậm: 0,8f và 0,8V → P = 0,512", "html": "<p class=\"mt-calc\">P<sub>1 nhân<\/sub> = 0,8² × 0,8 = <b>0,512<\/b><\/p>", "ask": {"q": "Giảm cả V và f xuống 0,8 lần. Công suất của một nhân còn bao nhiêu (gốc là 1)?", "o": ["0,8", "0,64", "0,512"], "a": 2}}, {"t": "Hai nhân: P ≈ 1,02, tốc độ tới 1,6 (nếu song song hoàn toàn)", "html": "<p class=\"mt-calc\">P = 2 × 0,512 = <b>1,024<\/b> · tốc độ ≤ 2 × 0,8 = <b>1,6<\/b><\/p><div class=\"mt-bars\"><div><span>1 nhân: P<\/span><span><i class=\"\" style=\"width:50.0%\"><\/i><em>1<\/em><\/span><\/div><div><span>2 nhân: P<\/span><span><i class=\"w\" style=\"width:51.2%\"><\/i><em>1,024<\/em><\/span><\/div><div><span>1 nhân: tốc độ<\/span><span><i class=\"\" style=\"width:50.0%\"><\/i><em>1<\/em><\/span><\/div><div><span>2 nhân: tốc độ<\/span><span><i class=\"o\" style=\"width:80.0%\"><\/i><em>≤ 1,6<\/em><\/span><\/div><\/div>", "say": "<p>Gần như cùng công suất nhưng làm được nhiều việc hơn, <b>nếu<\/b> công việc chia được cho hai nhân. Đây là lý do CPU hai nhân, bốn nhân trở nên phổ biến từ khoảng năm 2005. Mô hình bỏ qua công suất rò và giới hạn của bộ nhớ.<\/p>"}]}, {"label": "Ví dụ: Định luật Amdahl với p = 0,9", "note": "Phần tuần tự 10% giới hạn tốc độ tối đa ở 10 lần.", "steps": [{"t": "Phần song song hóa được p = 0,9", "html": "<p class=\"mt-calc\">S(n) = 1 ÷ ((1 − p) + p ÷ n) · phần tuần tự 1 − p = 0,1 luôn chạy trên một nhân<\/p>", "say": "<p>Định luật Amdahl (Gene Amdahl, 1967): phần tuần tự không được tăng tốc dù có bao nhiêu nhân.<\/p>"}, {"t": "1 nhân: nhanh × 1", "html": "<p class=\"mt-calc\">S(1) = 1 ÷ (0,1 + 0,9) = <b>1<\/b><\/p><div class=\"mt-bars\"><div><span>1 nhân<\/span><span><i class=\"\" style=\"width:10.0%\"><\/i><em>× 1<\/em><\/span><\/div><\/div>"}, {"t": "2 nhân: nhanh × 1,82", "html": "<p class=\"mt-calc\">S(2) = 1 ÷ (0,1 + 0,45) = <b>1,82<\/b><\/p><div class=\"mt-bars\"><div><span>1 nhân<\/span><span><i class=\"\" style=\"width:10.0%\"><\/i><em>× 1<\/em><\/span><\/div><div><span>2 nhân<\/span><span><i class=\"\" style=\"width:18.2%\"><\/i><em>× 1,82<\/em><\/span><\/div><\/div>"}, {"t": "4 nhân: nhanh × 3,08", "html": "<p class=\"mt-calc\">S(4) = 1 ÷ (0,1 + 0,225) = <b>3,08<\/b><\/p><div class=\"mt-bars\"><div><span>1 nhân<\/span><span><i class=\"\" style=\"width:10.0%\"><\/i><em>× 1<\/em><\/span><\/div><div><span>2 nhân<\/span><span><i class=\"\" style=\"width:18.2%\"><\/i><em>× 1,82<\/em><\/span><\/div><div><span>4 nhân<\/span><span><i class=\"\" style=\"width:30.8%\"><\/i><em>× 3,08<\/em><\/span><\/div><\/div>"}, {"t": "8 nhân: nhanh × 4,71", "html": "<p class=\"mt-calc\">S(8) = 1 ÷ (0,1 + 0,1125) = <b>4,71<\/b><\/p><div class=\"mt-bars\"><div><span>1 nhân<\/span><span><i class=\"\" style=\"width:10.0%\"><\/i><em>× 1<\/em><\/span><\/div><div><span>2 nhân<\/span><span><i class=\"\" style=\"width:18.2%\"><\/i><em>× 1,82<\/em><\/span><\/div><div><span>4 nhân<\/span><span><i class=\"\" style=\"width:30.8%\"><\/i><em>× 3,08<\/em><\/span><\/div><div><span>8 nhân<\/span><span><i class=\"\" style=\"width:47.1%\"><\/i><em>× 4,71<\/em><\/span><\/div><\/div>", "ask": {"q": "p = 0,9. Với 8 nhân, chương trình nhanh hơn khoảng bao nhiêu lần?", "o": ["8 lần", "Khoảng 4,7 lần", "10 lần"], "a": 1}}, {"t": "16 nhân: nhanh × 6,4", "html": "<p class=\"mt-calc\">S(16) = 1 ÷ (0,1 + 0,0563) = <b>6,4<\/b><\/p><div class=\"mt-bars\"><div><span>1 nhân<\/span><span><i class=\"\" style=\"width:10.0%\"><\/i><em>× 1<\/em><\/span><\/div><div><span>2 nhân<\/span><span><i class=\"\" style=\"width:18.2%\"><\/i><em>× 1,82<\/em><\/span><\/div><div><span>4 nhân<\/span><span><i class=\"\" style=\"width:30.8%\"><\/i><em>× 3,08<\/em><\/span><\/div><div><span>8 nhân<\/span><span><i class=\"\" style=\"width:47.1%\"><\/i><em>× 4,71<\/em><\/span><\/div><div><span>16 nhân<\/span><span><i class=\"\" style=\"width:64.0%\"><\/i><em>× 6,4<\/em><\/span><\/div><\/div>"}, {"t": "∞ nhân: nhanh × 10", "html": "<p class=\"mt-calc\">S(∞) = 1 ÷ (0,1 + 0) = <b>10<\/b><\/p><div class=\"mt-bars\"><div><span>1 nhân<\/span><span><i class=\"\" style=\"width:10.0%\"><\/i><em>× 1<\/em><\/span><\/div><div><span>2 nhân<\/span><span><i class=\"\" style=\"width:18.2%\"><\/i><em>× 1,82<\/em><\/span><\/div><div><span>4 nhân<\/span><span><i class=\"\" style=\"width:30.8%\"><\/i><em>× 3,08<\/em><\/span><\/div><div><span>8 nhân<\/span><span><i class=\"\" style=\"width:47.1%\"><\/i><em>× 4,71<\/em><\/span><\/div><div><span>16 nhân<\/span><span><i class=\"\" style=\"width:64.0%\"><\/i><em>× 6,4<\/em><\/span><\/div><div><span>∞ nhân<\/span><span><i class=\"e\" style=\"width:100.0%\"><\/i><em>× 10<\/em><\/span><\/div><\/div>", "say": "<p>Dù vô số nhân, tốc độ không vượt 1 ÷ (1 − p) = 10 lần. Từ 8 lên 16 nhân chỉ tăng từ × 4,7 lên × 6,4: thêm nhân ngày càng ít lợi.<\/p>"}]}, {"label": "Ví dụ: Giao việc cho CPU, GPU hay NPU", "note": "Mỗi loại bộ xử lý mạnh ở một kiểu công việc.", "steps": [{"t": "Ba loại bộ xử lý trong một SoC hiện đại", "html": "<div class=\"mt-flow\"><div class=\"mt-box on\"><b>CPU<\/b><small>vài tới vài chục nhân mạnh, linh hoạt<\/small><\/div><div class=\"mt-box\"><b>GPU<\/b><small>hàng nghìn đơn vị tính đơn giản<\/small><\/div><div class=\"mt-box\"><b>NPU<\/b><small>mạch chuyên cho mạng nơ-ron<\/small><\/div><\/div>", "say": "<p>Mỗi loại mạnh ở một kiểu công việc. Hệ điều hành và phần mềm giao việc cho đúng loại.<\/p>"}, {"t": "Trình duyệt web: nhiều rẽ nhánh, phản hồi từng thao tác → CPU", "html": "<div class=\"mt-flow\"><div class=\"mt-box on\"><b>CPU<\/b><\/div><div class=\"mt-box dim\"><b>GPU<\/b><\/div><div class=\"mt-box dim\"><b>NPU<\/b><\/div><\/div><p class=\"mt-calc\">Ít luồng, nhiều quyết định khác nhau; cần nhân mạnh, đoán rẽ nhánh tốt.<\/p>"}, {"t": "Tô màu 2 triệu điểm ảnh mỗi khung hình → GPU", "html": "<div class=\"mt-flow\"><div class=\"mt-box dim\"><b>CPU<\/b><\/div><div class=\"mt-box on\"><b>GPU<\/b><\/div><div class=\"mt-box dim\"><b>NPU<\/b><\/div><\/div><p class=\"mt-calc\">Cùng một phép tính trên rất nhiều dữ liệu độc lập: hợp với hàng nghìn đơn vị tính đơn giản.<\/p>", "ask": {"q": "Tô màu 2 triệu điểm ảnh, mỗi điểm tính độc lập: loại nào hợp nhất?", "o": ["CPU", "GPU", "NPU"], "a": 1}}, {"t": "Nhận dạng khuôn mặt bằng mạng nơ-ron đã huấn luyện, trên điện thoại → NPU", "html": "<div class=\"mt-flow\"><div class=\"mt-box dim\"><b>CPU<\/b><\/div><div class=\"mt-box dim\"><b>GPU<\/b><\/div><div class=\"mt-box on\"><b>NPU<\/b><\/div><\/div><p class=\"mt-calc\">Chủ yếu là nhân ma trận với số độ chính xác thấp; mạch chuyên dụng tiết kiệm điện hơn nhiều.<\/p>"}, {"t": "Biên dịch một chương trình C++ → CPU", "html": "<div class=\"mt-flow\"><div class=\"mt-box on\"><b>CPU<\/b><\/div><div class=\"mt-box dim\"><b>GPU<\/b><\/div><div class=\"mt-box dim\"><b>NPU<\/b><\/div><\/div><p class=\"mt-calc\">Nhiều cấu trúc dữ liệu, rẽ nhánh phức tạp, khó chia thành hàng nghìn phần giống nhau.<\/p>"}]}, {"label": "Bẫy: Gấp đôi số nhân không gấp đôi tốc độ", "note": "Với p = 0,5, hai nhân chỉ nhanh khoảng 1,33 lần.", "steps": [{"t": "Phần song song hóa được p = 0,5", "html": "<p class=\"mt-calc\">S(n) = 1 ÷ ((1 − p) + p ÷ n) · phần tuần tự 1 − p = 0,5 luôn chạy trên một nhân<\/p>", "say": "<p>Định luật Amdahl (Gene Amdahl, 1967): phần tuần tự không được tăng tốc dù có bao nhiêu nhân.<\/p>"}, {"t": "1 nhân: nhanh × 1", "html": "<p class=\"mt-calc\">S(1) = 1 ÷ (0,5 + 0,5) = <b>1<\/b><\/p><div class=\"mt-bars\"><div><span>1 nhân<\/span><span><i class=\"\" style=\"width:50.0%\"><\/i><em>× 1<\/em><\/span><\/div><\/div>"}, {"t": "2 nhân: nhanh × 1,33", "html": "<p class=\"mt-calc\">S(2) = 1 ÷ (0,5 + 0,25) = <b>1,33<\/b><\/p><div class=\"mt-bars\"><div><span>1 nhân<\/span><span><i class=\"\" style=\"width:50.0%\"><\/i><em>× 1<\/em><\/span><\/div><div><span>2 nhân<\/span><span><i class=\"\" style=\"width:66.7%\"><\/i><em>× 1,33<\/em><\/span><\/div><\/div>", "ask": {"q": "Chỉ 50% chương trình chạy song song được. Hai nhân nhanh hơn bao nhiêu?", "o": ["2 lần", "Khoảng 1,33 lần", "1,5 lần"], "a": 1}}, {"t": "4 nhân: nhanh × 1,6", "html": "<p class=\"mt-calc\">S(4) = 1 ÷ (0,5 + 0,125) = <b>1,6<\/b><\/p><div class=\"mt-bars\"><div><span>1 nhân<\/span><span><i class=\"\" style=\"width:50.0%\"><\/i><em>× 1<\/em><\/span><\/div><div><span>2 nhân<\/span><span><i class=\"\" style=\"width:66.7%\"><\/i><em>× 1,33<\/em><\/span><\/div><div><span>4 nhân<\/span><span><i class=\"\" style=\"width:80.0%\"><\/i><em>× 1,6<\/em><\/span><\/div><\/div>"}, {"t": "∞ nhân: nhanh × 2", "html": "<p class=\"mt-calc\">S(∞) = 1 ÷ (0,5 + 0) = <b>2<\/b><\/p><div class=\"mt-bars\"><div><span>1 nhân<\/span><span><i class=\"\" style=\"width:50.0%\"><\/i><em>× 1<\/em><\/span><\/div><div><span>2 nhân<\/span><span><i class=\"\" style=\"width:66.7%\"><\/i><em>× 1,33<\/em><\/span><\/div><div><span>4 nhân<\/span><span><i class=\"\" style=\"width:80.0%\"><\/i><em>× 1,6<\/em><\/span><\/div><div><span>∞ nhân<\/span><span><i class=\"e\" style=\"width:100.0%\"><\/i><em>× 2<\/em><\/span><\/div><\/div>", "say": "<p>Với p = 0,5, kể cả vô số nhân cũng chỉ nhanh gấp 2. Trước khi mua thêm nhân, phải biết chương trình song song được bao nhiêu (Chương 6).<\/p>"}]}, {"label": "Lỗi: Tin “3 nm” là kích thước thật", "note": "Tên thế hệ công nghệ là tên thương mại.", "steps": [{"t": "Hai hãng cùng quảng cáo “3 nm”", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><b>Chip X<\/b><small>“3 nm”<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">vs<\/span><div class=\"mt-box\"><b>Chip Y<\/b><small>“3 nm”<\/small><\/div><\/div>", "say": "<p>Dễ nghĩ hai chip có transistor cùng kích thước 3 nanomét.<\/p>"}, {"t": "Thực tế: tên thế hệ là tên thương mại", "html": "<p class=\"mt-calc\">Tên thế hệ công nghệ không còn bằng chiều dài cực cổng hay bất kỳ kích thước cụ thể nào trên chip<\/p>", "ask": {"q": "Tên “3 nm” của một quy trình chế tạo cho biết chính xác điều gì?", "o": ["Chiều dài cực cổng là 3 nm", "Khoảng cách giữa hai transistor là 3 nm", "Đó là tên thế hệ, không bằng một kích thước cụ thể"], "a": 2}}, {"t": "Sửa: so sánh bằng số liệu đo được", "html": "<p class=\"mt-calc\">Mật độ transistor (transistor/mm²), hiệu năng và điện năng đo trên cùng bài thử<\/p>", "say": "<p>Các hãng đặt tên thế hệ theo cách riêng, nên “3 nm” của hai hãng có thể khác nhau về mật độ và hiệu năng. Muốn so sánh, dùng thông số công bố và phép đo có đối chứng (Chương 17).<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l7"),"l7",[{"kind": "num", "t": "Định luật Amdahl", "d": "<p>Dùng S(n) = 1 ÷ ((1 − p) + p ÷ n). Làm tròn 2 chữ số thập phân.<\/p>", "items": [{"q": "p = 0,8; n = 4. S = ?", "a": 2.5, "tol": 0.01}, {"q": "p = 0,95; n = 8. S = ?", "a": 5.925925925925925, "tol": 0.01}, {"q": "p = 0,9; n = 10. S = ?", "a": 5.2631578947368425, "tol": 0.01}, {"q": "p = 0,5; vô số nhân. S tối đa = ?", "a": 2, "tol": 0.01}], "hints": ["Tính phần tuần tự 1 − p trước, rồi cộng với p ÷ n.", "p = 0,8, n = 4: 0,2 + 0,2 = 0,4, nên S = 1 ÷ 0,4.", "Khi n rất lớn, p ÷ n gần bằng 0, nên S tối đa = 1 ÷ (1 − p)."], "why": "0,8 và 4 nhân: 1 ÷ 0,4 = 2,5; 0,95 và 8 nhân: 1 ÷ (0,05 + 0,11875) ≈ 5,93; 0,9 và 10 nhân: 1 ÷ 0,19 ≈ 5,26; 0,5 và vô số nhân: 1 ÷ 0,5 = 2."}, {"kind": "num", "t": "Công suất và nhịp của Moore", "d": "<p>Dùng P ≈ αCV²f với α, C không đổi; kết quả là số lần so với ban đầu. Làm tròn 3 chữ số thập phân.<\/p>", "items": [{"q": "f tăng 1,5 lần, V giữ nguyên. P gấp mấy lần?", "a": 1.5, "tol": 0.001}, {"q": "V giảm 10% (còn 0,9 lần), f giữ nguyên. P gấp mấy lần?", "a": 0.81, "tol": 0.001}, {"q": "f tăng 1,2 lần và V tăng 1,1 lần. P gấp mấy lần?", "a": 1.4520000000000002, "tol": 0.001}, {"q": "Nhân đôi mỗi 2 năm, sau 12 năm số transistor gấp mấy lần?", "a": 64}], "hints": ["P tỉ lệ thuận với f và với bình phương của V.", "V còn 0,9 lần thì V² còn 0,81 lần.", "12 năm là 6 lần nhân đôi: 2⁶."], "why": "P ∝ V²f: 1,5; 0,9² = 0,81; 1,1² × 1,2 = 1,452; 2⁶ = 64."}, {"kind": "pick", "t": "Giao việc cho bộ xử lý phù hợp", "d": "<p>Chọn loại bộ xử lý phù hợp nhất cho từng việc.<\/p>", "cats": ["CPU", "GPU", "NPU (bộ tăng tốc AI)"], "items": [{"q": "Xử lý thao tác người dùng trong trình soạn thảo văn bản", "a": 0}, {"q": "Vẽ cảnh 3D, tính màu cho hàng triệu điểm ảnh mỗi khung hình", "a": 1}, {"q": "Chạy mô hình nhận dạng giọng nói đã huấn luyện trên điện thoại, tiết kiệm pin", "a": 2}, {"q": "Biên dịch một dự án C++ lớn", "a": 0}, {"q": "Mô phỏng chuyển động của một triệu hạt, mỗi hạt tính cùng công thức", "a": 1}, {"q": "Làm mờ phông nền cuộc gọi video bằng mạng nơ-ron nhỏ trên laptop", "a": 2}], "hints": ["Nhiều rẽ nhánh, mỗi bước một quyết định khác nhau: CPU.", "Cùng một phép tính lặp trên rất nhiều dữ liệu độc lập: GPU.", "Chạy mạng nơ-ron đã huấn luyện, ưu tiên tiết kiệm điện: NPU."], "why": "Soạn thảo và biên dịch nhiều rẽ nhánh, hợp CPU; đồ họa 3D và mô phỏng hạt là song song dữ liệu, hợp GPU; nhận dạng giọng nói và làm mờ phông bằng mạng nơ-ron trên máy cá nhân hợp NPU."}]);

makeQuiz("quiz7","score7",[{"q": "Năm 1965, Gordon Moore nhận xét điều gì?", "o": ["Xung nhịp CPU tăng gấp đôi mỗi năm", "Giá máy tính giảm một nửa mỗi năm", "Số linh kiện trên một vi mạch tăng khoảng gấp đôi mỗi năm", "Transistor không thể nhỏ hơn 1 micromet"], "a": 2, "e": "Nhận xét là về số linh kiện trên một vi mạch (năm 1975 sửa thành khoảng hai năm), không phải về xung nhịp hay giá máy."}, {"q": "Theo P ≈ αCV²f, giảm điện áp V còn một nửa (các yếu tố khác giữ nguyên) thì công suất động còn bao nhiêu?", "o": ["Một nửa", "Một phần tư", "Không đổi", "Gấp đôi"], "a": 1, "e": "V nằm trong bình phương: (1/2)² = 1/4. Đó là lý do giảm điện áp là cách tiết kiệm điện hiệu quả nhất."}, {"q": "Chương trình có 50% chạy song song được. Dùng rất nhiều nhân thì nhanh hơn tối đa bao nhiêu lần?", "o": ["2 lần", "Vô hạn", "50 lần", "Bằng số nhân"], "a": 0, "e": "S tối đa = 1 ÷ (1 − p) = 1 ÷ 0,5 = 2. Phần tuần tự 50% không được tăng tốc."}, {"q": "Vì sao từ khoảng giữa thập niên 2000, xung nhịp CPU máy để bàn không còn tăng mạnh?", "o": ["Vì không ai cần máy nhanh hơn", "Vì định luật Moore bị bãi bỏ", "Vì transistor không thể đóng ngắt nhanh hơn 1 GHz", "Vì điện áp khó giảm tiếp, tăng xung nhịp làm công suất và nhiệt tăng quá nhanh"], "a": 3, "e": "Khi điện áp không giảm theo kích thước được nữa, mật độ công suất tăng theo xung nhịp; tản nhiệt trở thành giới hạn. Nhà sản xuất chuyển sang nhiều nhân và mạch chuyên dụng."}, {"q": "Việc nào hợp với GPU nhất?", "o": ["Áp cùng một phép tính lên hàng triệu điểm ảnh độc lập", "Xử lý từng phím gõ trong trình soạn thảo", "Chạy chương trình nhiều rẽ nhánh khó đoán", "Khởi động hệ điều hành"], "a": 0, "e": "GPU có hàng nghìn đơn vị tính đơn giản chạy cùng phép tính trên nhiều dữ liệu. Việc nhiều rẽ nhánh, tuần tự hợp với CPU hơn."}]);

